const LOGO="data:image/webp;base64,";
const $=s=>document.querySelector(s),app=$("#app");
let Q=[],i=0,A=[],S=[],U=[],W=[],T=false,SL=0,lock=false;
// floating background letters
$("#bg").innerHTML=Array.from({length:22},(_,k)=>`<span style="left:${Math.random()*100}%;font-size:${20+Math.random()*44}px;animation-duration:${14+Math.random()*18}s;animation-delay:-${Math.random()*20}s">${"ABCDEFGHIJKLMNOPRSTW?!✦★"[k]||"✦"}</span>`).join("");
function sh(a){a=[...a];for(let k=a.length-1;k>0;k--){const j=Math.floor(Math.random()*(k+1));[a[k],a[j]]=[a[j],a[k]]}return a}
function prep(){Q=R.map(r=>{const y=r[6]||"mc",q={l:r[0],g:r[1],q:r[2],e:r[4],p:r[5]||"",y,s:r[7]||""};if(y=="ty")q.a=r[3];else if(y=="or"){q.a=[r[3][0]];q.t=sh(r[3][0].split(" "))}else{q.o=sh(r[3].map((t,k)=>({t,ok:k==0})));q.c=q.o.findIndex(x=>x.ok)}return q})}
function boom(el){const r=el.getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height/2;for(let k=0;k<16;k++){const s=document.createElement("span");s.className="cf";s.textContent=["⭐","✨","🎉","💫","🌈"][k%5];s.style.cssText=`left:${x}px;top:${y}px;--dx:${(Math.random()-.5)*320}px;--dy:${(Math.random()-.8)*280}px`;document.body.appendChild(s);setTimeout(()=>s.remove(),1000)}}
function start(){app.innerHTML=`<div class="card"><img class="logo big" src="${LOGO}" alt="ELF Online English School"><h1>Level Quest</h1><p class="s">Приключение из 6 миров, по 17 заданий в каждом: грамматика, лексика, аудирование, правописание, порядок слов. Начни с самого начала или выбери свой мир!</p><div class="row"><button class="go" onclick="begin(0)">▶ Начать с самого начала</button></div><div class="kl row">Или выбери любой уровень:</div><div class="row">${IC.map((c,k)=>`<button class="sec lv" style="--lc:${LC[k]}" onclick="begin(${k})">${c} ${L[k]}<small>${NM[k]}</small><small><b>${R.filter(r=>r[0]==L[k]).length} заданий</b></small></button>`).join("")}</div></div>`}
function begin(sl){SL=sl||0;prep();i=Q.findIndex(q=>q.l==L[SL]);A=[];S=[];U=[];app.innerHTML=`<div class="brand"><img src="${LOGO}" height="44" style="vertical-align:middle" alt=""> Level Quest</div><div class="map" id="map"><div class="track"><i id="tr"></i></div>${L.map((l,k)=>`<div class="nd" style="left:${k/5*100}%" id="n${k}"><span>${IC[k]}</span><b>${l}</b></div>`).join("")}<div class="hero" id="hr" style="left:0">🧝‍♀️</div></div><div class="card" id="qc"></div>`;play()}
const need=n=>Math.ceil(n*.65),corr=q=>q.y=="mc"||q.y=="ls"?q.o[q.c].t:q.a[0];
function play(){lock=false;W=[];const q=Q[i],li=L.indexOf(q.l),ix=Q.filter(x=>x.l==q.l),j=ix.indexOf(q)+1;
$("#hr").style.left=li/5*100+"%";$("#tr").style.width=li/5*100+"%";L.forEach((_,k)=>$("#n"+k).className="nd "+(k<li?"done":k==li?"cur":""));
$("#qc").className="card"+(li<2?" kid":"");$("#qc").style.setProperty("--lc",LC[li]);
$("#qc").innerHTML=`<div class="tag">${IC[li]} ${ZN[li]} · ${q.l} · ${q.g} · вопрос ${j} из ${ix.length} · всего ${i+1}/${Q.length}</div><div class="bar"><i style="width:${(j-1)/ix.length*100}%"></i></div>${q.y=="ls"?`<div class="pic"><button class="go" style="margin:0" onclick="say()">▶ Play 🎧</button></div>`:q.p?`<div class="pic">${q.p}</div>`:""}<h2>${q.q} ${q.y=="ls"?"":`<button class="sp" onclick="say()" aria-label="Listen">🔊</button>`}</h2>${body(q)}${T?`<div class="fb g">👩‍🏫 Ответ: <b>${corr(q)}</b>${q.s?" · 🎧 "+q.s:""} — ${q.e}</div>`:""}<div id="fb"></div>`;
if(q.y=="ls")setTimeout(say,500)}
function body(q){if(q.y=="ty")return `<div class="row"><input id="ti" class="ti" autocomplete="off" placeholder="type here..." onkeydown="if(event.key=='Enter')sub()"><br><button class="go" onclick="sub()">Check ✓</button></div>`;
if(q.y=="or")return `<div class="ans" id="ao"></div><div class="row">${q.t.map((w,k)=>`<button class="op tk" onclick="tok(${k},this)">${w}</button>`).join("")}</div><div class="row"><button class="ghost" onclick="clr()">↺ Сначала</button><button class="go" style="display:inline-block" onclick="sub()">Check ✓</button></div>`;
return `<div class="opts">${q.o.map((o,k)=>`<button class="op${T&&k==q.c?" hint":""}" style="animation-delay:${k*.07}s" onclick="pick(${k},this)">${o.t}</button>`).join("")}</div>`}
function tok(k,el){if(lock)return;W.push(Q[i].t[k]);el.style.visibility="hidden";$("#ao").textContent=W.join(" ")}
function clr(){if(lock)return;W=[];document.querySelectorAll(".tk").forEach(x=>x.style.visibility="visible");$("#ao").textContent=""}
function sub(){if(lock)return;const q=Q[i],a=q.y=="ty"?$("#ti").value:W.join(" "),n=s=>s.toLowerCase().replace(/[’]/g,"'").replace(/[.,!?;]/g,"").replace(/\s+/g," ").trim();if(!n(a))return;fin(q.a.some(x=>n(x)==n(a)),a,$("#qc .go"))}
function say(){try{speechSynthesis.cancel();const q=Q[i],u=new SpeechSynthesisUtterance((q.s||q.q).replace(/_+/g,"blank"));u.lang="en-GB";u.rate=.85;speechSynthesis.speak(u)}catch(e){}}
function pick(k,el){fin(k==Q[i].c,Q[i].o[k].t,el)}
function fin(ok,ans,el){if(lock)return;lock=true;const q=Q[i],mc=q.y=="mc"||q.y=="ls";S[i]=ok;U[i]=ans;
document.querySelectorAll("#qc .op,#qc input").forEach((x,n)=>{x.disabled=true;if(mc&&n==q.c)x.classList.add("ok")});
document.querySelectorAll("#qc .ghost").forEach(x=>x.style.display="none");if(!mc)el.style.display="none";if(!ok&&mc)el.classList.add("no");if(ok)boom(el);
$("#fb").innerHTML=`<div class="fb ${ok?"g":"r"}">${ok?"🎉 "+["Great job!","Wow!","Magic!","Super!","Brilliant!"][i%5]+" Верно!":"💡 Не совсем. Правильно: <b>"+corr(q)+"</b>."} ${q.e}</div><button class="go" onclick="next()">${i<Q.length-1?"Дальше →":"Узнать результат ✨"}</button>`}
function next(){i++;if(i>=Q.length)result();else if(Q[i].l!=Q[i-1].l)check(Q[i-1].l);else play()}
function check(l){const li=L.indexOf(l),ix=Q.map((q,k)=>k).filter(k=>Q[k].l==l),sc=ix.filter(k=>S[k]).length,ok=sc>=need(ix.length);
app.innerHTML=`<img class="logo" style="width:110px" src="${LOGO}" alt=""><div class="card"><div class="badge">${IC[li]}</div><h1 style="font-size:30px">Мир ${l} пройден!</h1><p class="s">${ZN[li]} · верно ${sc} из ${ix.length} · ${ok?"✅ уровень освоен":"⚠️ есть пробелы"}</p>${gaps(ix)}<div class="row"><button class="go" onclick="play()">Следующий мир →</button><button class="ghost" onclick="result()">🏁 Завершить и получить итоговый отчёт</button></div></div>`;scrollTo(0,0);setTimeout(()=>boom($(".badge")),300)}
function gaps(ix){ix=(ix||Q.map((_,k)=>k)).filter(k=>S[k]!=null);const G={},K={},LX=["Vocabulary","Collocations","Spelling","Word formation","Phrasal verbs","Idioms","Irregular verbs"];
ix.forEach(k=>{const g=Q[k].g,s=g=="Listening"?"🎧 Аудирование":LX.includes(g)?"📖 Лексика":"🧩 Грамматика";[[G,g],[K,s]].forEach(([o,t])=>{const c=o[t]=o[t]||[0,0];c[1]++;if(S[k])c[0]++})});
const chip=([t,[a,b]])=>`<span class="chip ${a/b>=.75?"g":a/b<.4?"r":"y"}">${t} ${a}/${b}</span>`,miss=ix.filter(k=>!S[k]);
return `<div class="kl">📊 Навыки</div><div class="row">${Object.entries(K).map(chip).join("")}</div><div class="kl">🔍 Карта пробелов по темам</div><div class="row">${Object.entries(G).map(chip).join("")}</div><div class="kl">📚 Что повторить</div>${miss.length?miss.map(k=>`<div class="k">❌ <b>${Q[k].g}</b>: ${Q[k].q}<br>Правильно: <em>${corr(Q[k])}</em><small>${Q[k].e}</small></div>`).join(""):`<p class="s">Пробелов нет — отличная работа! 🌟</p>`}`}
function result(){const n=L.map(l=>Q.filter(q=>q.l==l).length),s=L.map(l=>Q.reduce((a,q,j)=>a+(q.l==l&&S[j]?1:0),0)),an=S.filter(x=>x!=null).length;let lv=-1;for(let k=0;k<6;k++){if(k<SL||s[k]>=need(n[k]))lv=k;else break}
app.innerHTML=`<img class="logo" style="width:130px" src="${LOGO}" alt=""><div class="card"><div class="badge">${lv<0?"🌟":IC[lv]}</div><div class="lvl">${lv<0?"Pre-A1":L[lv]}</div><p class="s"><b>${lv<0?"Стартовый уровень":NM[lv]}</b> · верно ${s.reduce((a,b)=>a+b)} из ${an} выполненных</p><p class="s">${lv<0?"Начнём с самых основ: алфавит, to be, первые слова. Всё впереди!":TIP[lv]}</p>${L.map((l,k)=>`<div class="rb"><b>${l}</b><div><i data-w="${k<SL?0:s[k]/n[k]*100}"></i></div><span>${k<SL?"—":s[k]+"/"+n[k]}</span></div>`).join("")}${SL?`<p class="s" style="font-size:13px">Вы начали с мира ${L[SL]}: предыдущие миры засчитаны как пройденные.</p>`:""}${gaps()}<p class="s" style="font-size:13px">Уровень засчитывается, если верно ≥65% заданий мира и пройдены все предыдущие миры.</p><div class="row"><button class="go" onclick="start()">↻ Пройти ещё раз / выбрать уровень</button></div></div>`;
setTimeout(()=>document.querySelectorAll(".rb i").forEach(e=>e.style.width=e.dataset.w+"%"),150);for(let k=0;k<4;k++)setTimeout(()=>boom($(".badge")),k*350);scrollTo(0,0)}
start();